class FindSumPairs {
private:
    vector<int> nums1;
    vector<int> nums2;
    unordered_map<int, int> counts2;
public:
    FindSumPairs(vector<int>& nums1, vector<int>& nums2) : nums1(nums1), nums2(nums2) {
        for (int x : nums2) counts2[x]++;
    }

    void add(int index, int val) {
        int old = nums2[index];
        counts2[old]--;
        nums2[index] += val;
        counts2[nums2[index]]++;
    }

    int count(int tot) {
        int res = 0;
        for (int x : nums1) {
            auto it = counts2.find(tot - x);
            if (it != counts2.end()) res += it->second;
        }
        return res;
    }
};

class FindSumPairs {
    private int[] nums1;
    private int[] nums2;
    private Map<Integer, Integer> counts2 = new HashMap<>();

    public FindSumPairs(int[] nums1, int[] nums2) {
        this.nums1 = nums1;
        this.nums2 = nums2;
        for (int x : nums2) counts2.put(x, counts2.getOrDefault(x, 0) + 1);
    }

    public void add(int index, int val) {
        int old = nums2[index];
        counts2.put(old, counts2.get(old) - 1);
        nums2[index] += val;
        counts2.put(nums2[index], counts2.getOrDefault(nums2[index], 0) + 1);
    }

    public int count(int tot) {
        int res = 0;
        for (int x : nums1) {
            res += counts2.getOrDefault(tot - x, 0);
        }
        return res;
    }
}

